def pin(p, poly):
 r,c=p; inside=False
 for (r1,c1),(r2,c2) in zip(poly,poly[1:]+poly[:1]):
  if ((c1>c)!=(c2>c)):
   rr=(r2-r1)*(c-c1)/(c2-c1)+r1
   if r<rr: inside=not inside
 # include boundary rough
 return inside
